pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.assume(amount <= address(c).balance);
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        // Fund the contract
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(actor);
        c.sendTo(address(0xdead), amount);
        uint256 balanceAfter = address(c).balance;
        // Rule: if actor is not the owner, balance MUST NOT decrease
        if (actor != c.owner()) {
            assertTrue(balanceAfter == balanceBefore);
        } else {
            assertTrue(balanceAfter <= balanceBefore);
        }
    }
}

